INSERT INTO changelog (title, body, created_at) VALUES ('Воронку прибрано', 'Розділ «Воронка» прибрано з меню, головної і картки клієнта: ти працюєш з кількома великими клієнтами, і воронка не потрібна. На головній замість неї — плитка «Клієнти» (скільки активних і разом на місяць). Статус «лід» у клієнта лишився. Старі посилання на воронку відкривають список клієнтів.', datetime('now'));
